16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
41	    private static final Map<String, String> CITY_REGION = Map.of(
42	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
43	
44	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
45	     *  {@link #getLocality()} in preference to the city. */
46	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
47	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
48	
49	    @Column(name = "address")
50	    @NotEmpty
51	    private String address;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "membership_number")
82	    private String membershipNumber;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "household_size")
88	    private Integer householdSize;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    /**
110	     * The canonical region derived for this owner. The {@link #postcode} is consulted
111	     * first: when it is present and falls within a known region's inclusive 4-digit
112	     * range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) that
113	     * region is returned. Only when the postcode is absent or in no known range does
114	     * this fall back to the fixed city-to-region table ({@code Sydney -> NSW},
115	     * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), returning {@code "UNKNOWN"}
116	     * when the city is not in the table either. This yields the same region for the
117	     * known cities while disambiguating cities that share a name via their postcode.
118	     * Derived (not persisted); recomputed from the current fields each call.
119	     *
120	     * @return the canonical region string, or {@code "UNKNOWN"}
121	     */
122	    @Transient
123	    public String getLocality() {
124	        String byPostcode = regionForPostcode(this.postcode);
125	        if (byPostcode != null) {
126	            return byPostcode;
127	        }
128	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
129	    }
130	
131	    /**
132	     * The region whose inclusive postcode range contains the given postcode, or
133	     * {@code null} when the postcode is absent, not a four-digit number, or in no
134	     * known range.
135	     */
136	    private static String regionForPostcode(String postcode) {
137	        if (postcode == null || !postcode.matches("\\d{4}")) {
138	            return null;
139	        }
140	        int value = Integer.parseInt(postcode);
141	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
142	            int[] range = entry.getValue();
143	            if (value >= range[0] && value <= range[1]) {
144	                return entry.getKey();
145	            }
146	        }
147	        return null;
148	    }
149	
150	    /**
151	     * The owner's membership level, a number from 1 to 3 assigned at creation:
152	     * starting at 1, add 1 when an {@link #email} is present and add 1 when
153	     * {@link #namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
154	     * Derived (not persisted); recomputed from the current fields each call.
155	     *
156	     * @return the membership level, from 1 to 3
157	     */
158	    @Transient
159	    public Integer getMembershipLevel() {
160	        int level = 1;
161	        if (this.email != null && !this.email.isBlank()) {
162	            level++;
163	        }
164	        if (this.namesakeCount != null && this.namesakeCount == 0) {
165	            level++;
166	        }
167	        return Math.min(level, 3);
168	    }
169	
170	    /**
171	     * The owner's preferred contact channel: {@code "EMAIL"} when an
172	     * {@link #email} is present, otherwise {@code "PHONE"}. Derived (not
173	     * persisted); recomputed from the current fields each call.
174	     *
175	     * @return {@code "EMAIL"} or {@code "PHONE"}
176	     */
177	    @Transient
178	    public String getContactPreference() {
179	        if (this.email != null && !this.email.isBlank()) {
180	            return "EMAIL";
181	        }
182	        return "PHONE";
183	    }
184	
185	    public String getTelephone() {
186	        return this.telephone;
187	    }
188	
189	    public void setTelephone(String telephone) {
190	        this.telephone = telephone;
191	    }
192	
193	    public String getEmail() {
194	        return this.email;
195	    }
196	
197	    public void setEmail(String email) {
198	        this.email = email;
199	    }
200	
201	    public String getPostcode() {
202	        return this.postcode;
203	    }
204	
205	    public void setPostcode(String postcode) {
206	        this.postcode = postcode;
207	    }
208	
209	    public LocalDate getRegistrationDate() {
210	        return this.registrationDate;
211	    }
212	
213	    public void setRegistrationDate(LocalDate registrationDate) {
214	        this.registrationDate = registrationDate;
215	    }
216	
217	    public String getCustomerCode() {
218	        return this.customerCode;
219	    }
220	
221	    public void setCustomerCode(String customerCode) {
222	        this.customerCode = customerCode;
223	    }
224	
225	    public String getHouseholdId() {
226	        return this.householdId;
227	    }
228	
229	    public void setHouseholdId(String householdId) {
230	        this.householdId = householdId;
231	    }
232	
233	    public Integer getNamesakeCount() {
234	        return this.namesakeCount;
235	    }
236	
237	    public void setNamesakeCount(Integer namesakeCount) {
238	        this.namesakeCount = namesakeCount;
239	    }
240	
241	    public String getMembershipNumber() {
242	        return this.membershipNumber;
243	    }
244	
245	    public void setMembershipNumber(String membershipNumber) {
246	        this.membershipNumber = membershipNumber;
247	    }
248	
249	    public Boolean getBulkSignupWarning() {
250	        return this.bulkSignupWarning;
251	    }
252	
253	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
254	        this.bulkSignupWarning = bulkSignupWarning;
255	    }
256	
257	    public Integer getHouseholdSize() {
258	        return this.householdSize;
259	    }
260	
261	    public void setHouseholdSize(Integer householdSize) {
262	        this.householdSize = householdSize;
263	    }
264	
265	    /**
266	     * The single derived key used for duplicate detection, formed as
267	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
268	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
269	     * is the stored (lower-cased) email or the empty string when absent, and the
270	     * household component is the stored {@link #householdId} or the empty string
271	     * when the owner belongs to no household. Two owners are duplicates of each
272	     * other exactly when their whole identity keys are equal; because the telephone
273	     * is part of the key, two members of the same household with different
274	     * telephones have different identity keys. Derived (not persisted); recomputed
275	     * from the current fields each call.
276	     *
277	     * @return the owner's identity key
278	     */
279	    @Transient
280	    public String getIdentityKey() {
281	        String tel = this.telephone == null ? "" : this.telephone;
282	        String mail = this.email == null ? "" : this.email;
283	        String household = this.householdId == null ? "" : this.householdId;
284	        return tel + "|" + mail + "|" + household;
285	    }
286	
287	    /**
288	     * A stable, normalised key identifying this owner's household (same last name
289	     * and address). The last name is folded case- and whitespace-insensitively and
290	     * the address is reduced to its canonical form exactly as in
291	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
292	     * household.
293	     *
294	     * @return the household key
295	     */
296	    public String householdKey() {
297	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
298	    }
299	
300	    /**
301	     * Whether this owner belongs to the same household as {@code other}: that is,
302	     * they share the same last name and address. The last name is compared
303	     * case-insensitively with runs of whitespace collapsed to a single space (and
304	     * surrounding whitespace trimmed); the address is compared in its canonical
305	     * normalised form (see {@link #normalizeAddress(String)}).
306	     *
307	     * @param other the owner to compare against
308	     * @return {@code true} if both owners share a household
309	     */
310	    public boolean sameHouseholdAs(Owner other) {
311	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
312	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
313	    }
314	
315	    /**
316	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
317	     * trim, collapse internal runs of whitespace to a single space and lower-case.
318	     */
319	    private static String normalize(String value) {
320	        if (value == null) {
321	            return "";
322	        }
323	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
324	    }
325	
326	    /**
327	     * Reduce an address to its canonical stored form: trim and collapse runs of
328	     * whitespace to a single space, upper-case, and expand common abbreviations
329	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
330	     * they appear as whole words. The result is what is stored, returned and used
331	     * for every household comparison; it is idempotent, so re-normalising an
332	     * already-normalised address leaves it unchanged.
333	     *
334	     * @param value the raw address (may be {@code null})
335	     * @return the normalised address, or the empty string if {@code value} is
336	     *         {@code null} or blank
337	     */
338	    public static String normalizeAddress(String value) {
339	        if (value == null) {
340	            return "";
341	        }
342	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
343	        if (collapsed.isEmpty()) {
344	            return "";
345	        }
346	        String[] tokens = collapsed.split(" ");
347	        for (int i = 0; i < tokens.length; i++) {
348	            tokens[i] = switch (tokens[i]) {
349	                case "ST" -> "STREET";
350	                case "RD" -> "ROAD";
351	                case "AVE" -> "AVENUE";
352	                default -> tokens[i];
353	            };
354	        }
355	        return String.join(" ", tokens);
356	    }
357	
358	    protected Set<Pet> getPetsInternal() {
359	        if (this.pets == null) {
360	            this.pets = new HashSet<>();
361	        }
362	        return this.pets;
363	    }
364	
365	    protected void setPetsInternal(Set<Pet> pets) {
366	        this.pets = pets;
367	    }
368	
369	    public List<Pet> getPets() {
370	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
371	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
372	        return Collections.unmodifiableList(sortedPets);
373	    }
374	
375	    public void setPets(List<Pet> pets) {
376	        this.pets = new HashSet<>(pets);
377	    }
378	
379	    public void addPet(Pet pet) {
380	        getPetsInternal().add(pet);
381	        pet.setOwner(this);
382	    }
383	
384	    /**
385	     * Return the Pet with the given name, or null if none found for this Owner.
386	     *
387	     * @param name to test
388	     * @return true if pet name is already in use
389	     */
390	    public Pet getPet(String name) {
391	        return getPet(name, false);
392	    }
393	
394	    /**
395	     * Return the Pet with the given name, or null if none found for this Owner.
396	     *
397	     * @param name to test
398	     * @return true if pet name is already in use
399	     */
400	    public Pet getPet(String name, boolean ignoreNew) {
401	        name = name.toLowerCase();
402	        for (Pet pet : getPetsInternal()) {
403	            if (!ignoreNew || !pet.isNew()) {
404	                String compName = pet.getName();
405	                compName = compName.toLowerCase();
406	                if (compName.equals(name)) {
407	                    return pet;
408	                }
409	            }
410	        }
411	        return null;
412	    }
413	
414	    public Pet getPet(Integer petId) {
415	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
416	    }
417	
418	    @Override
419	    public String toString() {
420	        return new ToStringCreator(this)
421	
422	            .append("id", this.getId())
423	            .append("new", this.isNew())
424	            .append("lastName", this.getLastName())
425	            .append("firstName", this.getFirstName())
426	            .append("address", this.address)
427	            .append("city", this.city)
428	            .append("telephone", this.telephone)
429	            .toString();
430	    }
431	}
