56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        if (!normalizeNewOwner(owner)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (dailyLimitReached(owner.getRegistrationDate())) {
117	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
118	        }
119	        if (cityIsAtCapacity(owner.getCity())) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        Optional<Owner> householdMember = findHouseholdMember(owner);
123	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
124	            joinHousehold(owner, householdMember.get());
125	        }
126	        if (identityKeyAlreadyUsed(owner)) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
130	        owner.setNamesakeCount(countNamesakes(owner));
131	        owner.setMembershipNumber(membershipNumber(owner));
132	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
133	        owner.setHouseholdSize(householdSize(owner));
134	        this.clinicService.saveOwner(owner);
135	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
136	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        String email = ownerFieldsDto.getEmail();
156	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        this.clinicService.deleteOwner(owner);
170	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        HttpHeaders headers = new HttpHeaders();
181	        Pet pet = petMapper.toPet(petFieldsDto);
182	        owner.setId(ownerId);
183	        pet.setOwner(owner);
184	        pet.getType().setName(null);
185	        this.clinicService.savePet(pet);
186	        PetDto petDto = petMapper.toPetDto(pet);
187	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
188	            .buildAndExpand(pet.getId()).toUri());
189	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner != null) {
197	            Pet currentPet = this.clinicService.findPetById(petId);
198	            if (currentPet != null) {
199	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
200	                currentPet.setName(petFieldsDto.getName());
201	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
202	                this.clinicService.savePet(currentPet);
203	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	            }
205	        }
206	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
212	        HttpHeaders headers = new HttpHeaders();
213	        Visit visit = visitMapper.toVisit(visitFieldsDto);
214	        Pet pet = new Pet();
215	        pet.setId(petId);
216	        visit.setPet(pet);
217	        this.clinicService.saveVisit(visit);
218	        VisitDto visitDto = visitMapper.toVisitDto(visit);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
220	            .buildAndExpand(visit.getId()).toUri());
221	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
222	    }
223	
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner != null) {
230	            Pet pet = owner.getPet(petId);
231	            if (pet != null) {
232	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    /**
239	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
240	     * the canonical form each stored value must take: the address is trimmed,
241	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
242	     * telephone is converted to E.164, any email is lower-cased and a missing
243	     * registration date defaults to today. Field-level rejections are reported here
244	     * rather than inline in {@link #addOwner}, and normalisation runs before any
245	     * household comparison so those comparisons see the canonical values.
246	     *
247	     * @param owner the freshly-mapped owner to normalise
248	     * @return {@code true} if the fields are valid, or {@code false} if the address
249	     *         is blank after normalisation or the telephone cannot form a valid
250	     *         E.164 number, in which case the request must be rejected with
251	     *         {@code 400 Bad Request}
252	     */
253	    private boolean normalizeNewOwner(Owner owner) {
254	        String address = Owner.normalizeAddress(owner.getAddress());
255	        if (address.isEmpty()) {
256	            return false;
257	        }
258	        owner.setAddress(address);
259	        String telephone = toE164(owner.getTelephone());
260	        if (telephone == null) {
261	            return false;
262	        }
263	        owner.setTelephone(telephone);
264	        if (owner.getEmail() != null) {
265	            owner.setEmail(owner.getEmail().toLowerCase());
266	        }
267	        if (!postcodeValidForCity(owner)) {
268	            return false;
269	        }
270	        if (owner.getRegistrationDate() == null) {
271	            owner.setRegistrationDate(LocalDate.now());
272	        }
273	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
274	        return true;
275	    }
276	
277	    /** Region -> inclusive 4-digit postcode range {low, high}. */
278	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
279	        "NSW", new int[] {2000, 2099},
280	        "VIC", new int[] {3000, 3099},
281	        "QLD", new int[] {4000, 4099});
282	
283	    /**
284	     * Validate the owner's postcode when one is supplied. A postcode is optional: an
285	     * owner created without one is accepted. When present it must be exactly four
286	     * digits and, when the owner's city maps to a known region (see
287	     * {@link Owner#getLocality()}), fall within that region's inclusive postcode
288	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
289	     * region accepts any four-digit postcode.
290	     *
291	     * @param owner the freshly-mapped owner being created
292	     * @return {@code true} if the postcode is absent or valid, {@code false} if it is
293	     *         malformed or out of range for the city's region (reject with 400)
294	     */
295	    private static boolean postcodeValidForCity(Owner owner) {
296	        String postcode = owner.getPostcode();
297	        if (postcode == null) {
298	            return true;
299	        }
300	        if (!postcode.matches("\\d{4}")) {
301	            return false;
302	        }
303	        int[] range = REGION_POSTCODES.get(owner.getLocality());
304	        if (range == null) {
305	            return true;
306	        }
307	        int value = Integer.parseInt(postcode);
308	        return value >= range[0] && value <= range[1];
309	    }
310	
311	    /**
312	     * Roll the given date forward to the next business day when it falls on a
313	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
314	     * weekday is returned unchanged. Applied to the effective registration date
315	     * (whether supplied in the request or defaulted to the server date) so that
316	     * every value derived from it uses the adjusted business day.
317	     *
318	     * @param date the effective registration date
319	     * @return the same date if it is a weekday, otherwise the next Monday
320	     */
321	    private static LocalDate rollToBusinessDay(LocalDate date) {
322	        switch (date.getDayOfWeek()) {
323	            case SATURDAY:
324	                return date.plusDays(2);
325	            case SUNDAY:
326	                return date.plusDays(1);
327	            default:
328	                return date;
329	        }
330	    }
331	
332	    /**
333	     * Determine whether the candidate owner's identity key collides with any existing
334	     * owner's. This is the single, consolidated duplicate check: it subsumes the
335	     * former separate telephone, email and household checks by comparing the whole
336	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
337	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
338	     * that agree on some — but not all — of the key's parts (for example two members of
339	     * the same household with different telephones) are not duplicates. Evaluated after
340	     * normalisation and household resolution, so the candidate's key reflects its
341	     * canonical field values and any household it has joined.
342	     *
343	     * @param owner the candidate owner being created, after household resolution
344	     * @return {@code true} if an existing owner has the same identity key
345	     */
346	    private boolean identityKeyAlreadyUsed(Owner owner) {
347	        String identityKey = owner.getIdentityKey();
348	        return this.clinicService.findAllOwners().stream()
349	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
350	    }
351	
352	    /**
353	     * Find an existing owner that belongs to the same household as the given owner,
354	     * i.e. shares the same last name and address (compared case-insensitively with
355	     * runs of whitespace collapsed to a single space).
356	     *
357	     * @param owner the candidate owner being created
358	     * @return the matching existing owner, or empty if none exists
359	     */
360	    private Optional<Owner> findHouseholdMember(Owner owner) {
361	        return this.clinicService.findAllOwners().stream()
362	            .filter(existing -> existing.sameHouseholdAs(owner))
363	            .findFirst();
364	    }
365	
366	    /**
367	     * Assign the joining owner and an existing household member the same stable
368	     * household identifier. The identifier is derived deterministically from the
369	     * shared household key (last name + address, normalised), so every owner in a
370	     * household resolves to the same value; the existing member is updated when it
371	     * does not already carry it.
372	     *
373	     * @param owner    the owner being created
374	     * @param existing an existing owner in the same household
375	     */
376	    private void joinHousehold(Owner owner, Owner existing) {
377	        String householdId = UUID
378	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
379	        owner.setHouseholdId(householdId);
380	        if (!householdId.equals(existing.getHouseholdId())) {
381	            existing.setHouseholdId(householdId);
382	            this.clinicService.saveOwner(existing);
383	        }
384	    }
385	
386	    /**
387	     * Count how many owners belong to the given owner's household once this create
388	     * completes: the owners that already share its {@code householdId} plus the owner
389	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
390	     * so the household identifier (and any existing member updated to it) is already in
391	     * place. An owner that has not joined a household (no {@code householdId}) is a
392	     * household of one.
393	     *
394	     * @param owner the candidate owner being created, after household resolution
395	     * @return the household member count after this create (at least {@code 1})
396	     */
397	    private int householdSize(Owner owner) {
398	        String householdId = owner.getHouseholdId();
399	        if (householdId == null) {
400	            return 1;
401	        }
402	        long existing = this.clinicService.findAllOwners().stream()
403	            .filter(other -> householdId.equals(other.getHouseholdId()))
404	            .count();
405	        return (int) existing + 1;
406	    }
407	
408	    /**
409	     * Count the existing owners that share the given owner's first and last name,
410	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
411	     * before the new owner is saved, so the result reflects only owners that
412	     * already existed at creation time.
413	     *
414	     * @param owner the candidate owner being created
415	     * @return the number of existing namesakes
416	     */
417	    private int countNamesakes(Owner owner) {
418	        String firstName = normalizeName(owner.getFirstName());
419	        String lastName = normalizeName(owner.getLastName());
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
422	                && normalizeName(existing.getLastName()).equals(lastName))
423	            .count();
424	    }
425	
426	    private static String normalizeName(String value) {
427	        return value == null ? "" : value.trim().toLowerCase();
428	    }
429	
430	    /**
431	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
432	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
433	     * first three letters of the given last name and NNNN a per-city 4-digit
434	     * zero-padded sequence equal to one more than the number of owners already in
435	     * that city (e.g. {@code SYD-SMI-0007}).
436	     *
437	     * @param city     the owner's city
438	     * @param lastName the owner's last name
439	     * @return the assigned customer code
440	     */
441	    /**
442	     * Determine whether the given city has already reached its owner capacity, i.e.
443	     * it already contains 50 or more existing owners (compared case-insensitively
444	     * with surrounding whitespace trimmed). A new owner may not be created in a city
445	     * that is at capacity.
446	     *
447	     * @param city the candidate owner's city
448	     * @return {@code true} if the city already holds 50 or more owners
449	     */
450	    private boolean cityIsAtCapacity(String city) {
451	        String normalizedCity = normalizeName(city);
452	        long count = this.clinicService.findAllOwners().stream()
453	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
454	            .count();
455	        return count >= 50;
456	    }
457	
458	    /**
459	     * Determine whether the daily owner-creation limit has already been reached, i.e.
460	     * 100 or more owners already carry the given registration date. A new owner may
461	     * not be created once that day's cap is reached.
462	     *
463	     * @param registrationDate the registration date the new owner would be created with
464	     * @return {@code true} if 100 or more existing owners share that registration date
465	     */
466	    private boolean dailyLimitReached(LocalDate registrationDate) {
467	        long count = this.clinicService.findAllOwners().stream()
468	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
469	            .count();
470	        return count >= 100;
471	    }
472	
473	    /**
474	     * Determine whether more than 80 owners have already been created for the given
475	     * registration date, i.e. strictly more than 80 existing owners carry that date.
476	     * Evaluated before the new owner is saved, so it reflects only owners that
477	     * already existed at creation time.
478	     *
479	     * @param registrationDate the registration date the new owner would be created with
480	     * @return {@code true} if more than 80 existing owners share that registration date
481	     */
482	    private boolean bulkSignupWarning(LocalDate registrationDate) {
483	        long count = this.clinicService.findAllOwners().stream()
484	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
485	            .count();
486	        return count > 80;
487	    }
488	
489	    private String nextCustomerCode(String city, String lastName) {
490	        String city3 = prefix3(city);
491	        String last3 = prefix3(lastName);
492	        long sequence = this.clinicService.findAllOwners().stream()
493	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
494	            .count() + 1L;
495	        return String.format("%s-%s-%04d", city3, last3, sequence);
496	    }
497	
498	    private static String prefix3(String value) {
499	        String v = value == null ? "" : value;
500	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
501	    }
502	
503	    /**
504	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
505	     * where {@code <customerCode>} is the owner's already-assigned customer code and
506	     * YY is the last two digits of the registration date's year (e.g.
507	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
508	     * have been set.
509	     *
510	     * @param owner the owner being created, with customer code and registration date
511	     *              already assigned
512	     * @return the assigned membership number
513	     */
514	    private String membershipNumber(Owner owner) {
515	        int yy = owner.getRegistrationDate().getYear() % 100;
516	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
517	    }
518	
519	    /**
520	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
521	     * code when present, otherwise assume country code '+61' and drop a single
522	     * leading '0' from the national digits. Spaces, dashes and brackets are
523	     * stripped. The result must contain 8 to 15 digits after the '+'.
524	     *
525	     * <p>In addition, the national-number length is validated against the country
526	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
527	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
528	     * whose national-number length is wrong for its country code is rejected.
529	     *
530	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
531	     *         input cannot form a valid E.164 number.
532	     */
533	    private static String toE164(String raw) {
534	        if (raw == null) {
535	            return null;
536	        }
537	        String cleaned = raw.replaceAll("[\\s()-]", "");
538	        String digits;
539	        if (cleaned.startsWith("+")) {
540	            digits = cleaned.substring(1);
541	        } else {
542	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
543	            digits = "61" + national;
544	        }
545	        if (!digits.matches("\\d{8,15}")) {
546	            return null;
547	        }
548	        if (!nationalNumberLengthValid(digits)) {
549	            return null;
550	        }
551	        return "+" + digits;
552	    }
553	
554	    /**
555	     * Validate the length of the national number (the digits after the country
556	     * code) against the country code carried by the given E.164 digit string: a
557	     * {@code 61} (Australia) number requires exactly 9 national digits and a
558	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
559	     * without a pinned length are accepted (only the generic 8-15 digit rule
560	     * applies to them).
561	     *
562	     * @param digits the E.164 digits without the leading '+'
563	     * @return {@code true} if the national-number length is correct for the country
564	     */
565	    private static boolean nationalNumberLengthValid(String digits) {
566	        if (digits.startsWith("61")) {
567	            return digits.length() - 2 == 9;
568	        }
569	        if (digits.startsWith("1")) {
570	            return digits.length() - 1 == 10;
571	        }
572	        return true;
573	    }
574	}
